//! `.stoweignore`: the paths stowe refuses to track.
//!
//! Media trees are full of things nobody wants versioned - `.DS_Store`,
//! `Thumbs.db`, `.thumbnails/` regenerated by a phone's gallery, editor scratch
//! files. Without a way to exclude them they get hashed, committed, pushed, and
//! (worst of all) reported as drift on every mirror that regenerates them.
//!
//! The file lives at the repo root, one pattern per line:
//!
//! ```text
//! # comments and blank lines are skipped
//! # a bare name matches that file or folder anywhere
//! .DS_Store
//! # `*` matches any run, `?` exactly one, within a segment
//! *.tmp
//! # a trailing slash matches directories only
//! .thumbnails/
//! # a pattern with a slash is anchored at the repo root
//! Renders/proxies/
//! ```
//!
//! A `#` only starts a comment at the beginning of a line; anywhere else it is
//! part of the pattern.
//!
//! Anything inside an ignored directory is ignored too. The rules apply to
//! every tree walk - the working tree *and* a mirror's - so junk a drive
//! recreates by itself never reads as drift. Naming a file explicitly
//! (`stowe add junk.tmp`) still stages it: an exact path you typed wins, and
//! the file stays tracked from then on.

use std::collections::HashSet;
use std::path::Path;

/// A parsed `.stoweignore`.
pub struct Ignore {
    rules: Vec<Rule>,
    /// Tracked paths, and every directory holding one: never ignored, since a
    /// file staged by name must stay visible to every walk that looks for it.
    kept: HashSet<String>,
}

struct Rule {
    /// The pattern split on `/`. Unanchored rules always hold exactly one.
    segs: Vec<String>,
    /// Pattern ended in `/`, so it matches directories only.
    dir_only: bool,
    /// Pattern held (or started with) a `/`, so it is matched against the whole
    /// repo-relative path rather than against a bare name.
    anchored: bool,
}

impl Ignore {
    /// Read `<root>/.stoweignore`. A missing or unreadable file means "ignore
    /// nothing", which is what every repo made before this feature existed
    /// wants.
    pub fn load(root: &Path) -> Ignore {
        let text = fs_err::read_to_string(root.join(".stoweignore")).unwrap_or_default();
        Ignore::parse(&text)
    }

    pub fn parse(text: &str) -> Ignore {
        let mut rules = Vec::new();
        for line in text.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let dir_only = line.ends_with('/');
            // A leading `/` only anchors; it is not part of the name to match.
            let body = line.trim_matches('/');
            if body.is_empty() {
                continue;
            }
            rules.push(Rule {
                anchored: body.contains('/') || line.starts_with('/'),
                segs: body.split('/').map(str::to_string).collect(),
                dir_only,
            });
        }
        Ignore {
            rules,
            kept: HashSet::new(),
        }
    }

    /// The same rules, except that `tracked` paths are never ignored.
    pub fn keeping<'a>(mut self, tracked: impl IntoIterator<Item = &'a str>) -> Ignore {
        for path in self.naming(tracked) {
            let mut end = path.len();
            while !self.kept.contains(&path[..end]) {
                self.kept.insert(path[..end].to_string());
                match path[..end].rfind('/') {
                    Some(slash) => end = slash,
                    None => break,
                }
            }
        }
        self
    }

    /// The files in `tracked` a rule names, by name or by a folder they are in.
    pub fn naming<'a>(&self, tracked: impl IntoIterator<Item = &'a str>) -> Vec<&'a str> {
        let mut named = Vec::new();
        if self.rules.is_empty() {
            return named;
        }
        // A manifest lists a folder's files one after another, so whether a
        // rule names the folder or one above it is worked out once per folder.
        let mut folder: Option<(&str, bool)> = None;
        for path in tracked {
            let dir = path.rsplit_once('/').map_or("", |(dir, _)| dir);
            let above = match folder {
                Some((d, named)) if d == dir => named,
                _ => {
                    let named = !dir.is_empty() && self.rule_names(dir, true);
                    folder = Some((dir, named));
                    named
                }
            };
            if above || self.matches(path, false) {
                named.push(path);
            }
        }
        named
    }

    /// Is this repo-relative path excluded?
    ///
    /// Ancestors are checked as well as the path itself, so a file buried in an
    /// ignored directory is still ignored even when the caller walked into it
    /// instead of pruning at the top.
    pub fn is_ignored(&self, rel: &str, is_dir: bool) -> bool {
        if self.rules.is_empty() || self.kept.contains(rel) {
            return false;
        }
        self.rule_names(rel, is_dir)
    }

    /// Whether a rule names `rel` or a folder it is in, tracked or not.
    fn rule_names(&self, rel: &str, is_dir: bool) -> bool {
        if self.matches(rel, is_dir) {
            return true;
        }
        let mut start = 0;
        while let Some(pos) = rel[start..].find('/') {
            let end = start + pos;
            if self.matches(&rel[..end], true) {
                return true;
            }
            start = end + 1;
        }
        false
    }

    /// Whether a rule names `rel` or a folder it is in, for a walk that never
    /// steps into a folder it leaves out, so each name meets the rules once:
    /// `above` is that answer for the folder `rel` is in. The walk leaves `rel`
    /// out unless it is tracked or holds a tracked path, which makes it
    /// [`Ignore::is_ignored`] on an `Ignore` [`keeping`](Ignore::keeping) them.
    pub fn walking(&self, rel: &str, is_dir: bool, above: bool) -> bool {
        above || (!self.rules.is_empty() && self.matches(rel, is_dir))
    }

    fn matches(&self, path: &str, is_dir: bool) -> bool {
        let name = path.rsplit('/').next().unwrap_or(path);
        self.rules.iter().any(|r| r.matches(path, name, is_dir))
    }
}

impl Rule {
    /// `name` is the last segment of `path`.
    fn matches(&self, path: &str, name: &str, is_dir: bool) -> bool {
        if self.dir_only && !is_dir {
            return false;
        }
        if self.anchored {
            let mut segs = path.split('/');
            self.segs
                .iter()
                .all(|p| segs.next().is_some_and(|s| wildcard(p, s)))
                && segs.next().is_none()
        } else {
            wildcard(&self.segs[0], name)
        }
    }
}

/// Glob match inside a single path segment: `*` is any run of characters, `?`
/// is exactly one. Iterative with backtracking, so a pattern full of stars
/// can't blow the stack on a long name, and it allocates nothing, since every
/// walk asks it of every path and each of its folders.
fn wildcard(pat: &str, text: &str) -> bool {
    if !pat.contains(['*', '?']) {
        return pat == text;
    }
    let at = |s: &str, i: usize| s[i..].chars().next();
    // Byte offsets, always on a character boundary.
    let (mut pi, mut ti) = (0usize, 0usize);
    // Where to resume from if the last `*` turns out to have matched too
    // little: just past that `*`, and how much of the text it had taken.
    let mut star: Option<(usize, usize)> = None;
    while let Some(tc) = at(text, ti) {
        match at(pat, pi) {
            Some(pc) if pc == '?' || pc == tc => {
                pi += pc.len_utf8();
                ti += tc.len_utf8();
            }
            Some('*') => {
                star = Some((pi + 1, ti));
                pi += 1;
            }
            _ => match star {
                Some((after, mark)) => {
                    let mark = mark + at(text, mark).map_or(1, char::len_utf8);
                    star = Some((after, mark));
                    pi = after;
                    ti = mark;
                }
                None => return false,
            },
        }
    }
    pat[pi..].chars().all(|c| c == '*')
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn nothing_is_ignored_without_a_file() {
        let ig = Ignore::parse("");
        assert!(!ig.is_ignored("Photos/a.NEF", false));
    }

    #[test]
    fn a_bare_name_matches_at_any_depth() {
        let ig = Ignore::parse(".DS_Store");
        assert!(ig.is_ignored(".DS_Store", false));
        assert!(ig.is_ignored("Photos/2019/.DS_Store", false));
        assert!(!ig.is_ignored("Photos/DS_Store.NEF", false));
    }

    #[test]
    fn wildcards_stay_inside_one_segment() {
        let ig = Ignore::parse("*.tmp");
        assert!(ig.is_ignored("Renders/scratch.tmp", false));
        assert!(!ig.is_ignored("scratch.tmp.exr", false));
        assert!(wildcard("a?c", "abc"));
        assert!(!wildcard("a?c", "ac"));
        assert!(wildcard("*", "anything"));
    }

    #[test]
    fn a_trailing_slash_matches_directories_only() {
        let ig = Ignore::parse("cache/");
        assert!(ig.is_ignored("Photos/cache", true));
        assert!(!ig.is_ignored("Photos/cache", false));
        // ...and everything inside one.
        assert!(ig.is_ignored("Photos/cache/thumb.jpg", false));
    }

    #[test]
    fn a_slash_anchors_the_pattern_to_the_root() {
        let ig = Ignore::parse("Renders/proxies/");
        assert!(ig.is_ignored("Renders/proxies/shot.mov", false));
        // Same name, different place: not anchored there, so it stays.
        assert!(!ig.is_ignored("Video/Renders/proxies/shot.mov", false));
    }

    #[test]
    fn comments_and_blank_lines_are_skipped() {
        let ig = Ignore::parse("# junk\n\n  *.tmp  \n");
        assert!(ig.is_ignored("a.tmp", false));
        assert!(!ig.is_ignored("# junk", false));
    }
}
